    # Defensive defaults
    cells = observation.get("grid", [])
    pos = observation.get("position", observation.get("self_position", [0, 0]))
    x, y = pos[0], pos[1]

    # Helper: safe deltas within bounds if bounds provided
    # We assume a square grid with optional 'width' and 'height'
    w = observation.get("width", None)
    h = observation.get("height", None)
    if w is None and h is not None:
        w = h
    if h is None and w is not None:
        h = w
    if w is None and h is None:
        w, h = 10, 10  # fallback

    # Build a small defensive strategy:
    # 1) If resource nearby (positive value in observation["resources"] at neighboring cells), move toward.
    # 2) If an opponent nearby (pursuit_evasion scenarios), try to keep distance by moving away from closest agent.
    # 3) Otherwise, default to staying or small exploration.
    # Normalize: prefer staying at (0,0) if nothing to do.

    best_dx, best_dy = 0, 0

    # Helper to check cell resource
    def resource_at(dx, dy):
        rx, ry = x + dx, y + dy
        if "resources" in observation:
            res = observation["resources"]
            if isinstance(res, dict):
                key = (rx, ry)
                return res.get(key, 0)
            if isinstance(res, list) and len(res) > 0:
                # assume 2D list if provided
                if 0 <= rx < len(res) and 0 <= ry < len(res[0]):
                    return res[rx][ry]
        return 0

    # Check neighbors for resource > 0
    best_r = 0
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            if dx == 0 and dy == 0:
                continue
            if -1 <= dx <= 1 and -1 <= dy <= 1:
                r = resource_at(dx, dy)
                if r > best_r:
                    best_r = r
                    best_dx, best_dy = dx, dy
    # If a resource is found, move toward it; else, consider evasion
    if best_r > 0:
        return [best_dx, best_dy]

    # Pursuit evasion: detect nearby agents to avoid
    closest_dist = None
    ev_dx, ev_dy = 0, 0
    agents = observation.get("agents", [])
    def distance(ax, ay, bx, by):
        return max(abs(ax - bx), abs(ay - by))  # Chebyshev distance

    for a in agents:
        ax = a.get("x", a.get("pos_x", 0))
        ay = a.get("y", a.get("pos_y", 0))
        d = distance(x, y, ax, ay)
        if closest_dist is None or d < closest_dist:
            closest_dist = d
            # move away
            if ax >= x:
                dx = -1
            else:
                dx = 1
            if ay >= y:
                dy = -1
            else:
                dy = 1
            ev_dx, ev_dy = dx, dy

    if closest_dist is not None and closest_dist <= 2:
        # try to increase distance
        return [ev_dx, ev_dy]

    # Territory control / exploration: bias toward center if grid bounds known
    cx = int((w - 1) / 2)
    cy = int((h - 1) / 2)
    dx = 0
    dy = 0
    if x < cx:
        dx = 1
    elif x > cx:
        dx = -1
    if y < cy:
        dy = 1
    elif y > cy:
        dy = -1
    if dx != 0 or dy != 0:
        return [dx, dy]

    # Default stay
    return [0, 0]

